import Component from '../../common/Component';
import Icon from '../../common/components/Icon';
import classList from '../../common/utils/classList';
/**
 * A titled group of settings on an admin page.
 *
 * The heading and description sit above the fields at every screen size.
 *
 * @example
 * <SettingsSection label="Notifications" description="When we email your members." icon="fas fa-bell">
 *   {this.buildSettingComponent({ setting: 'acme.notify', type: 'bool', label: 'Notify on reply' })}
 * </SettingsSection>
 */
export default class SettingsSection extends Component {
  view(vnode) {
    const {
      className,
      label,
      description,
      icon,
      id,
      ...attrs
    } = this.attrs;
    const headingId = id ? `${id}-heading` : undefined;
    return m("section", Object.assign({
      className: classList(this.classNames(), className),
      id: id,
      "aria-labelledby": headingId
    }, attrs), m("header", {
      className: "SettingsSection-header"
    }, m("h3", {
      className: "SettingsSection-title",
      id: headingId
    }, icon ? m(Icon, {
      name: icon,
      className: "SettingsSection-icon"
    }) : null, label), description ? m("p", {
      className: "SettingsSection-description helpText"
    }, description) : null), m("div", {
      className: this.bodyClassNames()
    }, vnode.children));
  }
  classNames() {
    return 'SettingsSection';
  }
  bodyClassNames() {
    return 'SettingsSection-body';
  }
}
flarum.reg.add('core', 'admin/components/SettingsSection', SettingsSection);